<template>
  <div class="Rooms">
    <InfoBox
      v-for="room in rooms"
      :title="room.name"
      :subtitle="room.gamemode"
      :description="room.description"
      :backgroundImage="room.background"
      :key="room.id"
    >
      <template v-slot:middle
        ><div class="RoomPlayers">
          {{ room.players }}/{{ room.maxplayers
          }}<i class="fa-duotone fa-user-group"></i></div
      ></template>
      <template v-slot:right
        ><div class="RoomButton">
          <Button
            class="gm-button-outlined gm-button-rounded"
            :class="[
              { 'gm-button-secondary': room.players === room.maxplayers },
            ]"
            @click="joinHandler(room)"
            :disabled="
              currentRoom === room.name || room.players === room.maxplayers
            "
          >
            <template v-if="currentRoom === room.name">Joined</template>
            <template v-else-if="room.players === room.maxplayers"
              >Full</template
            >
            <template v-else>Join</template>
          </Button>
        </div></template
      >
    </InfoBox>
  </div>
</template>

<script>
import InfoBox from "./InfoBox.vue";
import Button from "./Button.vue";

export default {
  name: "Rooms",
  components: { InfoBox, Button },
  props: {
    currentRoom: {
      type: String,
    },
    rooms: {
      type: Array,
    },
    joinFunction: {},
  },
  methods: {
    joinHandler(room) {
      if (this.joinFunction === "RequestLobbySwitch") {
        /* eslint-disable */
        mp.trigger("RequestLobbySwitch", room.id, room.password);
      } else if (this.joinFunction === "RequestMinigameJoin") {
        /* eslint-disable */
        mp.trigger("RequestMinigameJoin", room.id);
      }
    },
  },
};
</script>

<style scoped lang="scss">
.Rooms {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-gap: 10px;
  overflow-y: auto !important;
  max-height: 720px;

  .RoomPlayers,
  .RoomButton {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    height: 100%;
    flex-shrink: 0;
  }

  .RoomButton {
    width: 100%;
    flex-basis: 100%;
    display: flex;
    width: 100%;
  }

  .RoomPlayers {
    flex-direction: column-reverse;
    font-size: 1.2em;

    color: darken($white-text, 25%);
    font-weight: 400;
  }
}
</style>
