<template>
  <div class="crosshair-wrap" :style="{ height: h, width: w }">
    <div
      v-for="(layer, index) in layers"
      :style="{ zIndex: layers.length + 1 - index }"
      :key="layer"
      class="crosshair-inner"
      v-show="!layer.hidden"
    >
      <Cross v-if="layer.type === 1" :settings="layer" />
      <Circle v-else-if="layer.type === 2" :settings="layer" />
    </div>
  </div>
</template>

<script>
import Circle from "./Types/Circle/Circle.vue";
import Cross from "./Types/Cross/Cross.vue";

export default {
  name: "Crosshair",
  components: { Circle, Cross },
  props: ["h", "w", "layers"],
};
</script>

<style lang="scss" scoped>
.crosshair-wrap {
  position: relative;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;

  .crosshair-inner {
    position: absolute;
  }
}
</style>
