<template>
  <div class="AuthPanelContainer">
    <div class="AuthPanel">
      <div class="AuthPanelInner">
        <Transition name="fade">
          <div v-if="authLoading" class="AuthPanelLoaderOverlay">
            <Transition name="slide-up">
              <i
                v-if="authSuccess"
                class="fa-duotone fa-circle-check AuthPanelLoaderSuccess"
              ></i>
              <i v-else class="fa-duotone fa-spinner-third fa-spin"></i>
            </Transition>
          </div>
        </Transition>
        <img :src="logoBig" alt="logo" class="AuthPanelLogo" />
        <div v-show="panelID === 0">
          <AuthLogin @toggleLogin="toggleLogin" ref="login" />
        </div>
        <div v-show="panelID === 1">
          <AuthRegister @toggleLogin="toggleLogin" ref="register" />
        </div>
        <div class="AuthPanelMediaControls">
          <i
            @click="
              volume < 0.01 ? (volume = 0) : (volume -= 0.01),
                changeVolume(volume)
            "
            class="fa-duotone fa-volume-low"
          ></i>
          <Slider
            min="0"
            max="1"
            step="0.01"
            v-model="volume"
            @input="changeVolume(volume)"
          />
          <i
            @click="
              volume > 0.99 ? (volume = 1) : (volume += 0.01),
                changeVolume(volume)
            "
            class="fa-duotone fa-volume-high"
          ></i>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import AuthLogin from "./AuthLogin.vue";
import AuthRegister from "./AuthRegister.vue";
import Slider from "../../components/Slider.vue";

import { ref } from "vue";
import { useSound } from "@vueuse/sound";

import backgroundAudio from "@/assets/sounds/auth-background-01.mp3";

export default {
  name: "AuthPanel",
  components: { AuthLogin, AuthRegister, Slider },
  data() {
    return {
      logoBig: require("@/assets/images/logo-big.png"),
      panelID: 0,
      authSuccess: false,
      authLoading: false,
      volume: 0.05,
    };
  },
  methods: {
    toggleLogin(id) {
      this.panelID = id;
    },
  },
  setup() {
    const volume = ref(0.1);

    const { play, stop } = useSound(backgroundAudio, {
      playbackRate: 1,
      volume,
      interrupt: true,
    });

    const changeVolume = (vol) => {
      volume.value = vol;
    };

    return {
      changeVolume,
      play,
      stop,
    };
  },
};
</script>

<style scoped lang="scss">
.AuthPanelLoaderOverlay {
  width: 100%;
  height: 100%;
  position: absolute;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 2;
  background: rgba($background, 0.95);

  i {
    font-size: 100px;
    color: $gray;
    position: absolute;
  }

  .AuthPanelLoaderSuccess {
    color: $green !important;
  }
}
.AuthPanelContainer {
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  position: relative;
}
.AuthPanel {
  background: $foreground;
  height: 100vh;
  width: 500px;
  position: absolute;
  right: 0;

  .AuthPanelInner {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;

    .AuthPanelLogo {
      height: 60px;
      margin-bottom: 5px;
    }

    .AuthPanelMediaControls {
      position: absolute;
      bottom: -50px;
      height: 100px;
      width: 100%;
      border-radius: 50px;
      background: $background;
      display: flex;
      justify-content: center;
      align-items: center;
      padding-bottom: 50px;
      color: $gray;
      i {
        margin: 0 5px;
        cursor: pointer;
      }
    }
  }
}
</style>
