<template>
  <transition name="slide-fade">
    <div
      v-if="enabled"
      class="LoadingScreen"
      :style="[
        {
          backgroundImage: `url(${
            this.images[Math.floor(Math.random() * this.images.length)]
          })`,
        },
      ]"
    >
      <div class="LoadingScreenLoader">
        <i class="fa-duotone fa-spinner-third fa-spin"></i>
      </div>
      <div v-if="tips" class="LoadingScreenTip">
        Tip: {{ this.tips[Math.floor(Math.random() * this.tips.length)] }}
      </div>
      <!-- <div class="LoadingScreenSocials">
      <img class="LoadingScreenQRCode" :src="qrDiscord" alt="qrDiscord" />
      <img class="LoadingScreenQRCode" :src="qrYoutube" alt="qrYoutube" />
    </div> -->
    </div>
  </transition>
</template>

<script>
export default {
  name: "LoadingScreen",
  data() {
    return {
      enabled: false,
      images: [
        require("@/assets/images/loadingscreen-01.jpeg"),
        require("@/assets/images/loadingscreen-02.png"),
      ],
      tips: [
        "You can change your own weather by going into Menu > Settings > Game > Weather.",
        "Make sure to join our Discord server for lots of benefits! (/discord)",
        "If you're bored in the lobby, check out our side modes: deathmatch, derby, freeroam, and more!",
        "Report rulebreakers using the /report command. If no admin is online, report them via our Discord server. (/discord)",
        "Have a cool suggestion for the server? Want to report a bug? Need help? Join our Discord today, we'd love to hear from you! (/discord)",
        "Tired of writing /o every time? Turn on 'Auto OOC' by going into Menu > Settings > Chat > Auto OOC.",
        "You can save your current outfit and load another outfit by using the (/outfit) command.",
        "Want to spawn in the same car as your friend(s)? You can squad up by using the (/squad) command. There is also (/sc) for squad chat.",
        "Tired of people with loud microphones? You can fully mute voice chat by going into Menu > Settings > Chat, and changing your 'Voice Mode' to 'Disabled'!",
        "Want to support us even more? You can donate and receive special benefits in return! Check out our store @ store.racenchase.com!",
        "Make sure to share the server with your friends to help it grow! We would greatly appreciate it. :)",
      ],
    };
  },
  methods: {
    show(time = 5000) {
      if (time === true) return (this.enabled = true);
      this.enabled = true;
      setTimeout(() => {
        this.enabled = false;
      }, time);
    },
    hide() {
      this.enabled = false;
    },
  },
};
</script>

<style scoped lang="scss">
.LoadingScreen {
  width: 100vw;
  height: 100vh;
  background: center center;
  position: relative;
  color: $white-text;
  position: absolute;
  z-index: 999;

  .LoadingScreenLoader {
    position: absolute;
    bottom: 10px;
    right: 10px;
    font-size: 50px;
  }

  .LoadingScreenTip {
    position: absolute;
    left: 10px;
    bottom: 10px;
    background: rgba($foreground, 0.5);
    padding: 10px;
    border-radius: $radius-md;
    font-weight: 400;
    margin-right: 100px;
  }

  .LoadingScreenSocials {
    position: absolute;
    top: 10px;
    right: 10px;
    display: flex;
    flex-direction: column;

    background: rgba($foreground, 0.5);
    border-radius: $radius-md;

    .LoadingScreenQRCode {
      height: 120px;
      width: 120px;
    }
  }
}
</style>
