<template>
  <div class="layers">
    <draggable
      :list="layers"
      item-key="index"
      v-bind="dragOptions"
      handle=".handle"
      :force-fallback="true"
    >
      <template #item="{ element, index }">
        <div class="layer">
          <CrosshairLayer
            @removeLayer="removeLayer"
            :index="index"
            :setting="element"
            @updateLayer="updateLayer"
            @cloneLayer="$emit('addLayer', $event)"
            :devMode="devMode"
          />
        </div>
      </template>
    </draggable>
    <div
      v-if="this.layers.length < 10"
      class="w-full flex items-center justify-center p-2 gap-3"
    >
      <Button @click="addLayer">New Layer</Button>
      <v-select
        v-model="newType"
        class="w-52"
        :options="[
          { label: 'Cross', value: 1 },
          { label: 'Circle', value: 2 },
        ]"
        :clearable="false"
        :searchable="false"
      ></v-select>
    </div>
  </div>
</template>

<script>
import CrosshairLayer from "./CrosshairLayer.vue";
// TODO Uljepsat code. (Mozda sa vue style classama)
// TODO Stavi da preview mude position absolute na top right. (Tako da kad scrollaju kroz crosshair settings da je uvjek vidljiv)
// TODO Dodat da mozes dodavati vise elementa od drugit typova aka stekanje typova. (Jedan preko drugog sa position absolute)
// TODO Dodoati jos typova. (Circle etc)
import draggable from "vuedraggable";
import Button from "../../../../../components/Button.vue";

export default {
  name: "CrosshairLayers",
  components: { CrosshairLayer, draggable, Button },
  props: ["layers"],
  emits: ["addLayer", "removeLayer", "updateLayer"],
  computed: {
    dragOptions() {
      return {
        animation: 200,
      };
    },
  },
  data() {
    return {
      drag: false,
      types: [
        { name: "Cross", value: 1 },
        { name: "Circle", value: 2 },
      ],
      newType: { label: "Cross", value: 1 },
      devMode: true,
    };
  },
  methods: {
    toggleSetting(id, event) {
      if (this.devMode) return;
      // eslint-disable-next-line no-undef
      mp.trigger("MenuChangeSettings", id, event);
    },
    removeLayer(index) {
      this.$emit("removeLayer", index);
    },
    updateLayer(index, layer) {
      this.$emit("updateLayer", index, layer);
    },
    addLayer() {
      if (this.layers.length >= 10) return;

      switch (this.newType.value) {
        case 1:
          this.$emit("addLayer", {
            name: "Layer Cross",
            hidden: false,
            sides: [true, true, true, true],
            type: 1,
            gap: "20",
            size: "20",
            width: "3",
            rotation: "0",
            radius: "0",
            color: "#e3e3e3",
            outline: {
              enable: false,
              width: "1",
              color: "#1f1f1f",
            },
            dot: {
              enabled: false,
              size: "3",
              radius: "0",
              color: "#e3e3e3",
            },
            offset: {
              top: "0",
              right: "0",
            },
          });
          break;
        case 2:
          this.$emit("addLayer", {
            name: "Layer Circle",
            hidden: false,
            type: 2,
            width: "2",
            color: "#e3e3e3",
            size: {
              separated: false,
              y: "20",
              x: "20",
            },
            rotation: "0",
            fill: {
              enabled: false,
              color: "#e3e3e3",
            },
            outline: {
              enabled: false,
              width: "2",
              color: "#1f1f1f",
            },
            offset: {
              top: "0",
              right: "0",
            },
          });
          break;
      }
    },
  },
};
</script>

<style lang="scss" scoped>
.layers {
  max-height: 660px;
  height: 660px;
  overflow: hidden;
  border-radius: $radius-sm;
  overflow-y: auto;
  padding-right: 5px;
  margin: 5px 0;
}
</style>
